// ── Concrete strategies ─────────────────────────────────────────
const StripeStrategy = {
  pay(amount, details) {
    console.log(`[Stripe] Charging $${amount} to card ending ${details.last4}`);
    return { success: true, provider: 'stripe', amount };
  }
};

const PayPalStrategy = {
  pay(amount, details) {
    console.log(`[PayPal] Sending $${amount} to ${details.email}`);
    return { success: true, provider: 'paypal', amount };
  }
};

const CryptoStrategy = {
  pay(amount, details) {
    console.log(`[Crypto] Broadcasting ${amount} ETH to ${details.wallet}`);
    return { success: true, provider: 'crypto', amount };
  }
};

// ── Context ──────────────────────────────────────────────────────
class Checkout {
  constructor(strategy) {
    this._strategy = strategy;
  }

  setStrategy(strategy) {
    this._strategy = strategy;   // swap at runtime
  }

  pay(amount, details) {
    if (!this._strategy) throw new Error('No payment strategy set');
    return this._strategy.pay(amount, details);
  }
}

// ── Usage ────────────────────────────────────────────────────────
const checkout = new Checkout(StripeStrategy);
checkout.pay(99.99, { last4: '4242' });
// [Stripe] Charging $99.99 to card ending 4242

checkout.setStrategy(PayPalStrategy);          // swap — no rewrite
checkout.pay(49.00, { email: 'user@example.com' });
// [PayPal] Sending $49 to user@example.com

// ── Sort strategy — built-in JS example ─────────────────────────
const products = [
  { name: 'Laptop', price: 999 },
  { name: 'Mouse',  price: 29  },
  { name: 'Desk',   price: 349 },
];

const byPrice = (a, b) => a.price - b.price;          // strategy 1
const byName  = (a, b) => a.name.localeCompare(b.name); // strategy 2

console.log([...products].sort(byPrice).map(p => p.name));
// ['Mouse', 'Desk', 'Laptop']
console.log([...products].sort(byName).map(p => p.name));
// ['Desk', 'Laptop', 'Mouse']

// ── Strategy interface contract (duck-typed) ─────────────────────
// Any object with execute(data) qualifies as a Strategy.

// ── Context skeleton ─────────────────────────────────────────────
class Context {
  constructor(strategy) { this._strategy = strategy; }
  setStrategy(s)        { this._strategy = s; }
  execute(data)         { return this._strategy.execute(data); }
}

// ── Concrete strategies ──────────────────────────────────────────
const BubbleSort = { execute: (arr) => { /* ... */ return arr; } };
const QuickSort  = { execute: (arr) => { /* ... */ return arr; } };
const MergeSort  = { execute: (arr) => { /* ... */ return arr; } };

// ── Select strategy based on input size ─────────────────────────
function getSortStrategy(arr) {
  if (arr.length < 10)   return BubbleSort;
  if (arr.length < 1000) return QuickSort;
  return MergeSort;
}

const sorter = new Context(BubbleSort);
const data   = Array.from({ length: 500 }, () => Math.random());
sorter.setStrategy(getSortStrategy(data));
sorter.execute(data);
